"""Start the CauseLens MCP server (stdio) from inside the installed Crew app.

Crew registers this file through the manifest's ``mcpServers`` entry (``python3 mcp_server.py``): a bare ``python3`` launcher whose relative
``.py`` argument is resolved against the app root, run under the interpreter that has this app's ``requirements.txt`` installed. Everything
the server needs is under this directory, so the app works after Crew copies it out of the source checkout:

* ``runtime/causelens``: the analytics and MCP code (generated by ``scripts/package_crew_app.py``);
* ``data/``: the observed reference data (``metrics_daily.csv`` and ``events.csv``). There is no answer key here and the server refuses to
  serve a file named like one.

Under stdio, stdout carries only protocol messages; anything else goes to stderr.
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "runtime"))

from causelens.mcp.__main__ import main  # noqa: E402 - the path above must be set first

if __name__ == "__main__":
    sys.exit(main([
        "--transport", "stdio", "--dataset", "reference", str(ROOT / "data" / "metrics_daily.csv"), str(ROOT / "data" / "events.csv"),
    ]))
